import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{static void check(String input,Map<String,Integer>frequency,int optimalLength){Object r=TaskBinding.encode(input);Map<String,String>codes=TaskBinding.codes(r);assertEquals(frequency,TaskBinding.frequencies(r));assertEquals(frequency.keySet(),codes.keySet());for(var a:codes.entrySet()){assertTrue(a.getValue().matches("[01]+"));for(var b:codes.entrySet())if(!a.getKey().equals(b.getKey()))assertFalse(b.getValue().startsWith(a.getValue()));}String bits=TaskBinding.bits(r);assertTrue(bits.matches("[01]*"));assertEquals(optimalLength,bits.length());int weighted=0;for(String word:frequency.keySet())weighted+=frequency.get(word)*codes.get(word).length();assertEquals(optimalLength,weighted);Map<String,String>decoded=new HashMap<>();for(var e:codes.entrySet())assertNull(decoded.put(e.getValue(),e.getKey()));List<String>words=new ArrayList<>();String pending="";for(char bit:bits.toCharArray()){pending+=bit;if(decoded.containsKey(pending)){words.add(decoded.get(pending));pending="";}}assertEquals("",pending);assertEquals(input.isEmpty()?List.of():Arrays.asList(input.split(" +")),words);}@Test void publishedOptimalPrefixAndEmpty(){check("one two two three three three",Map.of("one",1,"two",2,"three",3),9);check("",Map.of(),0);Object one=TaskBinding.encode("one one one");assertEquals(Map.of("one","0"),TaskBinding.codes(one));assertEquals("000",TaskBinding.bits(one));}}
